--- index.html
+++ index.html
@@ -15,9 +15,9 @@
     .music-toggle{border:1px solid var(--line);background:#fffefa9e;border-radius:100px;padding:10px 15px;display:inline-flex;align-items:center;gap:9px;cursor:pointer;font-size:13px;color:#66746a;transition:.2s}.music-toggle:hover{border-color:#b9c5b7;background:white}.music-toggle .sound-icon{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:#edf1e9;color:var(--green);font-size:13px}.music-toggle[aria-pressed="true"] .sound-icon{background:var(--green);color:white}.hint{font-size:12px;color:#9aa39c;margin-top:30px;line-height:1.6}
     .game-card{padding:clamp(18px,3vw,30px);border:1px solid #e8e5dc;border-radius:28px;background:#fffefa;box-shadow:var(--shadow);position:relative}.game-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:17px}.game-label{font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#7a877d}.round-badge{font-size:11px;color:#829083;background:#f2f4ee;padding:7px 11px;border-radius:30px}.board-wrap{position:relative}.board{display:grid;grid-template-columns:repeat(8,1fr);gap:6px;aspect-ratio:1;padding:9px;background:#f1f0e9;border-radius:18px;touch-action:none;user-select:none}.cell{border-radius:7px;background:#e4e6dc;transition:background .12s,transform .12s;position:relative}.cell.filled{background:var(--tile,#799681);box-shadow:inset 0 -3px 0 #00000012;animation:pop .18s ease-out}.cell.preview{background:#a6bba4!important;opacity:.72}.cell.invalid{background:#d9a39a!important;opacity:.8}.cell.clearing{animation:clear .27s ease-in forwards}@keyframes pop{from{transform:scale(.75)}to{transform:scale(1)}}@keyframes clear{50%{transform:scale(.82);opacity:.55}100%{transform:scale(.1);opacity:0}}
     .tray-title{display:flex;justify-content:space-between;align-items:center;margin:22px 2px 13px}.tray-title span:first-child{font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#7c887e}.tray-title small{font-size:11px;color:#a0a9a0}.pieces{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.piece{height:92px;border:1px solid #eeeae2;background:#fcfbf7;border-radius:14px;display:grid;place-items:center;cursor:pointer;transition:transform .18s,border .18s,background .18s;touch-action:none;position:relative}.piece:hover{transform:translateY(-2px);border-color:#d6dfd3}.piece.selected{background:#f3f6f0;border-color:#94ab95;box-shadow:0 0 0 2px #e3ebe1}.piece.used{opacity:.3;pointer-events:none}.piece-shape{display:grid;gap:4px;pointer-events:none}.mini-cell{width:18px;height:18px;border-radius:5px;background:var(--piece-color,#799681);box-shadow:inset 0 -2px #00000012}.mini-cell.empty{visibility:hidden}.toast{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%) scale(.9);padding:11px 16px;border-radius:30px;background:#34483a;color:white;font-size:13px;font-weight:600;white-space:nowrap;opacity:0;pointer-events:none;transition:.2s;z-index:2;box-shadow:0 7px 22px #30433535}.toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}
     .bottom-row{display:flex;justify-content:center;margin-top:19px}.new-game{border:0;background:#edf1e9;border-radius:30px;padding:10px 17px;color:#56705b;font-size:12px;font-weight:700;cursor:pointer;transition:.2s}.new-game:hover{background:#e3eade;transform:translateY(-1px)}.overlay{position:absolute;inset:0;border-radius:28px;background:#fffefaed;display:none;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:26px;z-index:3}.overlay.show{display:flex}.overlay h2{font:800 30px 'Manrope',sans-serif;letter-spacing:-.05em;margin:0 0 7px}.overlay p{color:#7d8980;font-size:14px;margin:0 0 22px}.overlay button{border:0;background:var(--green);color:white;border-radius:30px;padding:12px 22px;font-weight:700;cursor:pointer}
-    @media(max-width:750px){body{align-items:flex-start;padding:21px 15px 28px}.app{grid-template-columns:1fr;gap:21px;width:min(100%,440px)}.intro{padding:0;text-align:center}.brand{justify-content:center;font-size:10px}h1{font-size:43px;margin:14px 0 8px}.subtitle{font-size:13px;line-height:1.55;max-width:340px;margin:auto}.stats{justify-content:center;margin:16px 0 13px;gap:9px}.stat{min-width:112px;padding:9px 15px}.stat span{font-size:9px;margin-bottom:2px}.stat strong{font-size:21px}.music-toggle{padding:7px 12px;font-size:11px}.music-toggle .sound-icon{width:21px;height:21px}.hint{display:none}.game-card{padding:18px;border-radius:23px}.board{gap:5px;padding:8px;border-radius:15px}.cell{border-radius:6px}.piece{height:75px}.mini-cell{width:16px;height:16px;border-radius:4px}.tray-title{margin:17px 2px 10px}.bottom-row{margin-top:13px}}
+    @media(max-width:750px){body{align-items:flex-start;padding:16px 15px 28px}.app{grid-template-columns:1fr;gap:16px;width:min(100%,440px)}.intro{padding:0;text-align:center}.brand{justify-content:center;font-size:10px}h1{font-size:39px;margin:9px 0 6px}.subtitle{font-size:12px;line-height:1.5;max-width:340px;margin:auto}.stats{justify-content:center;margin:12px 0 9px;gap:9px}.stat{min-width:112px;padding:8px 15px}.stat span{font-size:9px;margin-bottom:2px}.stat strong{font-size:21px}.music-toggle{padding:6px 12px;font-size:11px}.music-toggle .sound-icon{width:21px;height:21px}.hint{display:none}.game-card{padding:18px;border-radius:23px}.board{gap:5px;padding:8px;border-radius:15px}.cell{border-radius:6px}.piece{height:75px}.mini-cell{width:16px;height:16px;border-radius:4px}.tray-title{margin:17px 2px 10px}.bottom-row{margin-top:13px}}
     @media(max-width:360px){:root{--cell:28px}.game-card{padding:14px}.board{gap:4px;padding:7px}.pieces{gap:6px}.piece{height:67px}.mini-cell{width:14px;height:14px}.subtitle{font-size:12px}}
   </style>
 </head>
